// Prepare Line Protocol (n8n Code node, Run Once for Each Item)
let m = $json.message;
if (typeof m === 'string') {
  m = JSON.parse(m);
}

const temperature = Number(m.temperature);
const humidity = Number(m.humidity);
const pressure = Number(m.pressure);
const gasKohm = Number(m.gas_kohm);

if ([temperature, humidity, pressure, gasKohm].some(Number.isNaN)) {
  throw new Error('Bad payload: ' + JSON.stringify(m));
}

// Tag values cannot contain spaces, commas or equals signs
const device = String(m.device || 'unknown').replace(/[ ,=]/g, '_');

const line = `bme680,device=${device} temperature=${temperature},humidity=${humidity},pressure=${pressure},gas_kohm=${gasKohm}`;

return { json: { line } };

// Build Report Facts (n8n Code node, Run Once for All Items)

// ---- Edit the alert thresholds here ----
const T = {
  humidityHigh: 70,    // %RH
  humidityLow: 30,     // %RH
  tempHigh: 32,        // C
  pressureDrop: -2.0,  // hPa change over the hour
  gasDropPct: 20       // % fall in gas resistance over the hour
};

const isTest = $execution.mode === 'test';
const csv = String($input.first().json.data ?? '');

// ---- Parse the annotated CSV from InfluxDB ----
const rows = [];
let header = null;
for (const raw of csv.split(/\r?\n/)) {
  const line = raw.trim();
  if (!line || line.startsWith('#')) continue;
  const cols = line.split(',');
  if (cols.includes('_value') && cols.includes('_field')) {
    header = cols;
    continue;
  }
  if (!header) continue;
  const rec = {};
  header.forEach((name, i) => { rec[name] = cols[i]; });
  const value = Number(rec._value);
  if (rec._field && !Number.isNaN(value)) {
    rows.push({ field: rec._field, time: rec._time, value });
  }
}

// ---- Summarise each field ----
const round = (x) => Math.round(x * 100) / 100;
const facts = {};
for (const field of ['temperature', 'humidity', 'pressure', 'gas_kohm']) {
  const values = rows
    .filter((r) => r.field === field)
    .sort((a, b) => a.time.localeCompare(b.time))
    .map((r) => r.value);
  if (values.length === 0) continue;
  const first = values[0];
  const last = values[values.length - 1];
  facts[field] = {
    readings: values.length,
    min: round(Math.min(...values)),
    max: round(Math.max(...values)),
    avg: round(values.reduce((a, b) => a + b, 0) / values.length),
    first: round(first),
    last: round(last),
    change: round(last - first)
  };
}

// ---- Apply the rules ----
const flags = [];
if (Object.keys(facts).length === 0) flags.push('no_data');
if (facts.humidity && facts.humidity.last > T.humidityHigh) flags.push('humidity_high');
if (facts.humidity && facts.humidity.last < T.humidityLow) flags.push('humidity_low');
if (facts.temperature && facts.temperature.last > T.tempHigh) flags.push('temperature_high');
if (facts.pressure && facts.pressure.change <= T.pressureDrop) flags.push('pressure_dropping');
if (facts.gas_kohm && facts.gas_kohm.first > 0) {
  const dropPct = ((facts.gas_kohm.first - facts.gas_kohm.last) / facts.gas_kohm.first) * 100;
  if (dropPct >= T.gasDropPct) flags.push('gas_resistance_falling');
}

// Scheduled runs only email when something is flagged. Test runs always email.
if (flags.length === 0 && !isTest) {
  return [];
}

const subject = flags.length
  ? 'BME680 alert: ' + flags.join(', ')
  : 'BME680 routine check';

const prompt = [
  'You are an assistant for an indoor environment sensor (BME680).',
  'Write a plain-text email body of at most 4 short sentences, then one final line that starts with "Action:".',
  'Use only the numbers given below. Never invent values. Do not state an air quality index.',
  'Units: temperature in C, humidity in %RH, pressure in hPa, gas in kOhm.',
  'Gas is a raw resistance. A falling trend can suggest worsening air quality, but it is only a relative signal.',
  'If the flag no_data is present, say that no readings arrived in the last hour and suggest checking power, Wi-Fi and the HiveMQ connection.',
  '',
  'Flags: ' + (flags.length ? flags.join(', ') : 'none, routine check'),
  'Last hour summary (JSON): ' + JSON.stringify(facts)
].join('\n');

return [{ json: { prompt, subject, flags, facts } }];
